#ifndef __INCLUDE_ASM_H__
#define __INCLUDE_ASM_H__

/*
 * INCLUDE_ASM(folder, name): emit a not-yet-decompiled function from asm/nonmatchings/<folder>/<name>.s.
 * Decompile by replacing the line with the C definition (Ship of Theseus); the build must stay matching.
 * The .s files are generated by `make split` (tools/gen_asm.py); each one carries its own .align/.global.
 */
#if !defined(NON_MATCHING) && !defined(SKIP_ASM)
#ifndef INCLUDE_ASM
#define INCLUDE_ASM(FOLDER, NAME) __asm__(".include \"" FOLDER "/" #NAME ".s\"")
#endif
#else
#define INCLUDE_ASM(FOLDER, NAME)
#endif

#endif /* __INCLUDE_ASM_H__ */
